import { NextRequest, NextResponse } from "next/server";
import { listAISummaries } from "@/lib/db";

export async function GET(_req: NextRequest, { params }: { params: { id: string } }) {
  return NextResponse.json(listAISummaries(params.id));
}

// In-memory data store for the hackathon v0.
// Swap-out point for Role A: replace this module's internals with a real
// DB (Postgres/Prisma or SQLite) while keeping the exported function
// signatures identical so nothing above this layer has to change.
//
// Survives Next.js dev-mode hot reload by hanging off globalThis.

import { nanoid } from "nanoid";
import type {
  Vehicle,
  VehicleComponent,
  Workflow,
  Requirement,
  Signal,
  SourceRecord,
  Stakeholder,
  StakeholderReview,
  AuditLogEntry,
  AISummary,
  Actor,
  AuditAction,
} from "./types";
import { buildSeed } from "./seed";

interface Store {
  vehicles: Vehicle[];
  components: VehicleComponent[];
  workflows: Workflow[];
  requirements: Requirement[];
  signals: Signal[];
  sources: SourceRecord[];
  stakeholders: Stakeholder[];
  reviews: StakeholderReview[];
  auditLog: AuditLogEntry[];
  aiSummaries: AISummary[];
}

const globalForStore = globalThis as unknown as { __ehlStore?: Store };

function freshStore(): Store {
  return buildSeed();
}

export const store: Store = globalForStore.__ehlStore ?? (globalForStore.__ehlStore = freshStore());

// ---------- append-only audit log ----------

export function logAction(entry: {
  workflowId: string;
  actor: Actor;
  action: AuditAction;
  targetType: AuditLogEntry["targetType"];
  targetId: string;
  oldValue: unknown;
  newValue: unknown;
  rationale: string;
}): AuditLogEntry {
  const full: AuditLogEntry = {
    id: `log_${nanoid(8)}`,
    timestamp: new Date().toISOString(),
    ...entry,
  };
  store.auditLog.push(full);
  return full;
}

export function getAuditLog(workflowId: string): AuditLogEntry[] {
  return store.auditLog
    .filter((l) => l.workflowId === workflowId)
    .sort((a, b) => a.timestamp.localeCompare(b.timestamp));
}

// ---------- vehicles / components ----------

export function listVehicles(): Vehicle[] {
  return store.vehicles;
}

export function getVehicle(id: string): Vehicle | undefined {
  return store.vehicles.find((v) => v.id === id);
}

export function listComponents(vehicleId: string): VehicleComponent[] {
  return store.components.filter((c) => c.vehicleId === vehicleId);
}

export function getComponent(componentId: string): VehicleComponent | undefined {
  return store.components.find((c) => c.id === componentId);
}

// ---------- workflows ----------

export function getWorkflow(workflowId: string): Workflow | undefined {
  return store.workflows.find((w) => w.id === workflowId);
}

export function getWorkflowByComponent(componentId: string): Workflow | undefined {
  const comp = getComponent(componentId);
  if (!comp?.workflowId) return undefined;
  return getWorkflow(comp.workflowId);
}

export function createWorkflow(componentId: string, market: string): Workflow {
  const comp = getComponent(componentId);
  if (!comp) throw new Error("component not found");
  const now = new Date().toISOString();
  const workflow: Workflow = {
    id: `wf_${nanoid(8)}`,
    vehicleId: comp.vehicleId,
    componentId,
    market,
    status: "draft",
    stages: [
      { key: "ingest", label: "Ingest datasets", status: "active", startedAt: now, completedAt: null, owner: "pm" },
      { key: "enrich", label: "Enrich with web knowledge", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "extract", label: "Extract signals", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "derive", label: "Derive requirements", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "score", label: "Score & prioritize", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "stakeholder_review", label: "Stakeholder review", status: "pending", startedAt: null, completedAt: null, owner: "stakeholder" },
      { key: "pm_decision", label: "PM decision", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
      { key: "deploy", label: "Move to deploy", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
    ],
    createdAt: now,
    updatedAt: now,
  };
  store.workflows.push(workflow);
  comp.workflowId = workflow.id;

  logAction({
    workflowId: workflow.id,
    actor: { type: "pm", id: "pm_demo", name: "Product Manager" },
    action: "workflow_created",
    targetType: "workflow",
    targetId: workflow.id,
    oldValue: null,
    newValue: { componentId, market },
    rationale: `Started a new requirements workflow for ${comp.label} in ${market}.`,
  });

  return workflow;
}

export function updateStage(
  workflowId: string,
  stageKey: Workflow["stages"][number]["key"],
  status: Workflow["stages"][number]["status"],
  actor: Actor,
) {
  const wf = getWorkflow(workflowId);
  if (!wf) throw new Error("workflow not found");
  const stage = wf.stages.find((s) => s.key === stageKey);
  if (!stage) throw new Error("stage not found");
  const oldStatus = stage.status;
  stage.status = status;
  const now = new Date().toISOString();
  if (status === "active" && !stage.startedAt) stage.startedAt = now;
  if (status === "complete") stage.completedAt = now;
  wf.updatedAt = now;

  logAction({
    workflowId,
    actor,
    action: "stage_transition",
    targetType: "stage",
    targetId: stageKey,
    oldValue: oldStatus,
    newValue: status,
    rationale: `${stage.label}: ${oldStatus} -> ${status}`,
  });
}

// ---------- requirements ----------

export function listRequirements(workflowId: string): Requirement[] {
  return store.requirements
    .filter((r) => r.workflowId === workflowId)
    .sort((a, b) => b.score - a.score);
}

export function getRequirement(id: string): Requirement | undefined {
  return store.requirements.find((r) => r.id === id);
}

export function recomputeScore(req: Requirement): number {
  const totalWeight = req.scoreFactors.reduce((s, f) => s + f.weight, 0) || 1;
  const weighted = req.scoreFactors.reduce((s, f) => s + (f.rawValue * f.weight), 0);
  return Math.round((weighted / totalWeight) * 10) / 10;
}

export function updateRequirementStatus(
  id: string,
  status: Requirement["status"],
  actor: Actor,
  rationale: string,
): Requirement {
  const req = getRequirement(id);
  if (!req) throw new Error("requirement not found");
  const oldStatus = req.status;
  req.status = status;
  req.updatedAt = new Date().toISOString();

  const actionMap: Record<Requirement["status"], AuditAction> = {
    proposed: "requirement_edited",
    approved: "requirement_approved",
    rejected: "requirement_rejected",
    postponed: "requirement_postponed",
    challenged: "requirement_challenged",
  };

  logAction({
    workflowId: req.workflowId,
    actor,
    action: actionMap[status],
    targetType: "requirement",
    targetId: req.id,
    oldValue: oldStatus,
    newValue: status,
    rationale,
  });

  return req;
}

export function updateWeights(
  requirementId: string,
  weights: Record<string, number>,
  actor: Actor,
): Requirement {
  const req = getRequirement(requirementId);
  if (!req) throw new Error("requirement not found");
  const oldScore = req.score;
  req.scoreFactors = req.scoreFactors.map((f) => ({
    ...f,
    weight: weights[f.key] ?? f.weight,
  }));
  req.score = recomputeScore(req);
  req.updatedAt = new Date().toISOString();

  logAction({
    workflowId: req.workflowId,
    actor,
    action: "weights_adjusted",
    targetType: "requirement",
    targetId: req.id,
    oldValue: { score: oldScore },
    newValue: { score: req.score, weights },
    rationale: "PM adjusted scoring factor weights.",
  });

  return req;
}

// ---------- signals / sources ----------

export function listSignals(workflowId: string): Signal[] {
  return store.signals.filter((s) => s.workflowId === workflowId);
}

export function listSources(workflowId: string): SourceRecord[] {
  return store.sources.filter((s) => s.workflowId === workflowId);
}

export function getSourcesByIds(ids: string[]): SourceRecord[] {
  return store.sources.filter((s) => ids.includes(s.id));
}

// ---------- stakeholders / reviews ----------

export function listStakeholders(): Stakeholder[] {
  return store.stakeholders;
}

export function getStakeholder(id: string): Stakeholder | undefined {
  return store.stakeholders.find((s) => s.id === id);
}

export function listReviews(workflowId: string): StakeholderReview[] {
  return store.reviews.filter((r) => r.workflowId === workflowId);
}

export function submitReview(
  reviewId: string,
  decision: StakeholderReview["decision"],
  expertOpinion: string,
): StakeholderReview {
  const review = store.reviews.find((r) => r.id === reviewId);
  if (!review) throw new Error("review not found");
  review.decision = decision;
  review.expertOpinion = expertOpinion;
  review.submittedAt = new Date().toISOString();

  const stakeholder = getStakeholder(review.stakeholderId);

  logAction({
    workflowId: review.workflowId,
    actor: { type: "stakeholder", id: review.stakeholderId, name: stakeholder?.name ?? "Stakeholder" },
    action: "stakeholder_review_submitted",
    targetType: "review",
    targetId: review.id,
    oldValue: { decision: "pending" },
    newValue: { decision, expertOpinion },
    rationale: expertOpinion,
  });

  return review;
}

// ---------- AI summaries ----------

export function listAISummaries(workflowId: string): AISummary[] {
  return store.aiSummaries.filter((s) => s.workflowId === workflowId);
}

export function addAISummary(summary: Omit<AISummary, "id" | "generatedAt">): AISummary {
  const full: AISummary = {
    ...summary,
    id: `aisum_${nanoid(8)}`,
    generatedAt: new Date().toISOString(),
  };
  store.aiSummaries.push(full);

  logAction({
    workflowId: summary.workflowId,
    actor: { type: "ai", id: "ai_engine", name: "Requirements Copilot", model: "claude-sonnet-5" },
    action: "ai_summary_generated",
    targetType: "workflow",
    targetId: summary.workflowId,
    oldValue: null,
    newValue: { type: summary.type },
    rationale: "Regenerated summary from latest audit log entries.",
  });

  return full;
}
=== DATA_SETUP
# Real data setup

The app is grounded in the real BMW hackathon datasets: 13,771 real customer
feedback rows across three vehicle lines, real sales volumes, real
multi-market customer-study benchmarks, and the real official equipment/
pricing documents. **None of this is in git** — it's confidential hackathon
material, not something to publish on a public repo. Every teammate needs
their own local copy.

## One-time setup (everyone, ~2 minutes)

1. Get the dataset files from wherever the team shared them (`F70_feedback_hackathon.xlsx`, `G60_feedback_hackathon.xlsx`, `G70_feedback_hackathon.xlsx`, `F70_G60_G68_G70_customer_studies.xlsx`, `sales_volumes.xlsx`, `F70_OptionList.PDF`, `G60_OptionList.PDF`, `G70_OptionList.PDF`).
2. Copy all 8 files into `data-raw/` at the repo root (gitignored — create the folder if it doesn't exist).
3. Convert the 3 PDFs to text (needs `poppler`: `brew install poppler` on macOS):
   ```bash
   cd data-raw
   for f in F70_OptionList G60_OptionList G70_OptionList; do
     pdftotext -layout "$f.PDF" "$f.txt"
   done
   cd ..
   ```
4. Run the ingestion pipeline:
   ```bash
   npm run ingest
   ```
   This writes `src/data/*.json` (also gitignored). Restart `npm run dev` to pick it up.

Without this, the app still runs — `src/lib/seed.ts` falls back to a small
hand-written mock workflow so nobody is blocked waiting on file access. You'll
know you're on the fallback if the landing page shows only one vehicle
("BMW 5 Series") with one workflow instead of three vehicles with ~17
workflows.

## What's actually in the data

| File | Rows/sheets | What it is |
|---|---|---|
| `{F70,G60,G70}_feedback_hackathon.xlsx` | ~4,000-5,000 rows each, sheet `Feedback_Explorer` | Real customer verbatims with BMW's own **VFC (Vehicle Feedback Classification)** taxonomy already applied: `Feedback Type` (Likes/Wants/Difficult to Use/Defect), `Vfc level2 Name` / `Vfc level3 Name` (226 real categories), country, engine type (ICE/BEVE/PHEV). |
| `sales_volumes.xlsx` | 3 sheets (`F70`, `G60_G68`, `G70`), 4 rows each | 2024/2025/2030(est.) sales volume by market. |
| `F70_G60_G68_G70_customer_studies.xlsx` | `CN_EU_2025` (36 categories × 5 models, direct 0-10 means), `US_2025` (satisfaction-bucket distributions for G60/G70) | Customer-study ratings comparing BMW models to each other — **not** external competitors. |
| `{F70,G60,G70}_OptionList.PDF` | Official BMW price/equipment configurator documents (German) | Standard/optional equipment by trim. |

F70 = 1 Series, G60 = 5 Series (G68 is its China long-wheelbase variant),
G70 = 7 Series.

## How ingestion turns this into the app's data model

See `scripts/ingest-real-data.ts` (the pipeline) and `scripts/lib/componentMap.ts`
(the category mapping) for the actual code. The short version:

1. **Feedback → FeedbackRecord[]**: straight column mapping, written to `src/data/feedback.json`. This is what powers the Evidence Explorer (`/evidence`).
2. **Component mapping**: BMW's 226 `Vfc level2 Name` categories are mapped onto our 6 landing-page components (exterior/interior/windows/steering/engine/battery) by keyword rules in `componentMap.ts` — deterministic and auditable on purpose, not an LLM call. Unmatched categories go to a `general` bucket (still browsable in the Evidence Explorer, just no landing-page hotspot).
3. **Signals**: feedback grouped by `(vehicleCode, component, theme)`, with real frequency counts and a `Feedback Type` breakdown standing in for sentiment — written to `src/data/signals.json`.
4. **Requirements**: `src/lib/deriveRequirements.ts` picks up to 4 signals per component (prioritizing pain points, then customer-requested gaps, then strengths worth protecting) and scores them **deterministically** — no LLM involved in v0's scoring. See that file's top comment for exactly which factors are real data vs. which are placeholders (`effort_inverse` is always a flat placeholder; `competitive_gap`/`strategic_fit` are the two factors Role B should eventually upgrade to a real LLM call with cited evidence — see `docs/ROLE_B_AI.md`).
5. **Sales relevance / competitive gap**: computed from real `sales_volumes.xlsx` growth and real `customer-study` cross-model comparisons — see the `STUDY_CATEGORY_KEYWORDS` mapping in `deriveRequirements.ts` for how customer-study categories (a *different* taxonomy than VFC) are matched to our 6 components.
6. **Equipment PDFs**: chunked by section header into raw text excerpts (`src/data/equipment-chunks.json`) for citation. **Known gap**: this does not parse the standard/optional equipment matrix into a structured per-trim feature table — the PDF's column-aligned layout (10+ trim columns, "■" markers) is brittle to parse reliably from `pdftotext -layout` output in the time available. If someone wants to extend this: the raw text is at `data-raw/*_OptionList.txt` after the pdftotext step, and the "AUSGEWÄHLTE SERIENAUSSTATTUNGEN" sections contain the matrix.

## The one hand-authored piece

Everything above is data-driven. The one exception: the BMW 5 Series /
Battery & Charging workflow (`wf_g60_battery`) has a scripted PM-challenge
→ AI-revision → stakeholder-review narrative layered on top of its
real top requirement, so the demo has a complete decision-trail story to
walk through even before Role B wires in live OpenAI calls. The requirement
title/numbers it references are computed live from real data (re-running
`npm run ingest` will shift them if the source data changes); only the
stakeholder dialogue and PM's challenge text are scripted. See
`buildFlagshipNarrative()` in `src/lib/seed.ts`.

## If you need to re-derive the mapping decisions

`scripts/lib/componentMap.ts`'s keyword rules were built by inspecting the
full 226-category list once (`node -e` one-liner over the parsed xlsx — not
checked in, but trivial to re-run with `XLSX.readFile` + a `Counter`-style
tally). If a re-ingest surfaces a miscategorized theme, the fix is a keyword
rule or an `OVERRIDES` entry in that file, not a code path change.

// Deterministic requirement derivation + scoring from real ingested data.
// No AI involved here on purpose — see docs/ROLE_B_AI.md for which of
// these factors stay deterministic forever (frequency, sales_relevance,
// evidence_strength) vs. which Role B upgrades to an LLM call with cited
// sources (competitive_gap, strategic_fit) once real web/competitor data
// is available. `effort` is intentionally never computed here — it's a
// placeholder until an Engineering stakeholder confirms it via review.

import type { ComponentKey, RequirementCategory, ScoreFactor } from "./types";
import type { RawSignal } from "./realData";
import type { CustomerStudyScore, SalesVolume } from "./types";

export type DerivedKind = "pain" | "opportunity" | "preserve";

export interface Candidate {
  signal: RawSignal;
  kind: DerivedKind;
  concentration: number; // 0-1, how dominant the driving sentiment is within this theme
}

export function classifySignal(signal: RawSignal): Candidate {
  const { frequency, likes, wants, difficultToUse, defect } = signal;
  const negative = difficultToUse + defect;
  const shares = [
    { kind: "preserve" as const, value: likes / frequency },
    { kind: "opportunity" as const, value: wants / frequency },
    { kind: "pain" as const, value: negative / frequency },
  ];
  shares.sort((a, b) => b.value - a.value);
  return { signal, kind: shares[0].kind, concentration: shares[0].value };
}

// Pick up to `max` signals for a component, prioritizing pain points,
// then customer-requested gaps, then strengths worth protecting (US-2.2) —
// in that order, since the brief asks us to focus on gaps/opportunities
// first and "must not lose" second.
export function pickCandidates(signals: RawSignal[], max = 4): Candidate[] {
  const classified = signals
    .map(classifySignal)
    .filter((c) => c.signal.frequency >= 3); // below this, not enough evidence to act on
  const byKind = (k: DerivedKind) =>
    classified.filter((c) => c.kind === k).sort((a, b) => b.signal.frequency - a.signal.frequency);

  const pains = byKind("pain");
  const opportunities = byKind("opportunity");
  const preserves = byKind("preserve");

  const picked: Candidate[] = [];
  picked.push(...pains.slice(0, 2));
  if (opportunities[0]) picked.push(opportunities[0]);
  if (preserves[0] && picked.length < max) picked.push(preserves[0]);
  return picked.slice(0, max);
}

const COMPONENT_TO_CATEGORY: Record<ComponentKey, RequirementCategory> = {
  battery: "range_charging",
  engine: "driving_experience",
  steering: "usability",
  windows: "comfort",
  interior: "comfort",
  exterior: "design_quality",
};

export function categoryFor(component: ComponentKey): RequirementCategory {
  return COMPONENT_TO_CATEGORY[component];
}

export function titleFor(candidate: Candidate): string {
  const { signal, kind } = candidate;
  if (kind === "pain") return `Reduce friction: ${signal.theme}`;
  if (kind === "opportunity") return `Deliver what customers are asking for: ${signal.theme}`;
  return `Protect this strength in the next generation: ${signal.theme}`;
}

export function descriptionFor(candidate: Candidate): string {
  const { signal, kind, concentration } = candidate;
  const pct = Math.round(concentration * 100);
  const countries = Object.entries(signal.countries)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([c]) => c)
    .join(", ");
  const sample = signal.sampleVerbatims[0]?.slice(0, 200) ?? "";
  const label =
    kind === "pain" ? "flagged as Difficult to Use / Defect" : kind === "opportunity" ? "explicitly requested (Wants)" : "called out as a Like";
  return `${signal.frequency} verbatims mention "${signal.theme}" (top markets: ${countries || "n/a"}); ${pct}% ${label}. Representative feedback: "${sample}${sample.length >= 200 ? "…" : ""}"`;
}

export function assumptionsFor(candidate: Candidate): string[] {
  if (candidate.kind === "opportunity") {
    return ["Assumes the requested capability stays technically and commercially viable through the next model year."];
  }
  if (candidate.kind === "preserve") {
    return ["Assumes competitors do not close this gap before the next generation launches."];
  }
  return [];
}

function evidenceLevel(frequency: number): "strong" | "moderate" | "weak" {
  if (frequency >= 15) return "strong";
  if (frequency >= 5) return "moderate";
  return "weak";
}

export function evidenceLevelFor(candidate: Candidate) {
  return evidenceLevel(candidate.signal.frequency);
}

// Keyword map from our 6 components to the customer-study's own category
// labels (its 36 categories are a different taxonomy than VFC, so this is
// a second, separate mapping — see docs/DATA_SETUP.md).
export const STUDY_CATEGORY_KEYWORDS: Record<ComponentKey, string[]> = {
  battery: ["fuel economy", "energy efficiency"],
  engine: ["acceleration", "roadholding", "sportiness"],
  steering: ["easy to read", "instruments", "navigation", "driving position"],
  windows: ["all round visibility", "visibility"],
  interior: ["interior", "seating", "roominess", "luggage", "comfort"],
  exterior: ["exterior styling", "build quality"],
};

export function competitiveGap(
  component: ComponentKey,
  vehicleCode: string,
  region: "CN" | "EU" | "US",
  study: CustomerStudyScore[],
): { value: number; rationale: string } {
  const keywords = STUDY_CATEGORY_KEYWORDS[component];
  const rows = study.filter(
    (r) => r.region === region && keywords.some((k) => r.category.toLowerCase().includes(k)),
  );
  if (rows.length === 0) {
    return { value: 50, rationale: "No customer-study category could be matched to this component; defaulting to neutral." };
  }
  const ours = rows.filter((r) => r.model.includes(vehicleCode));
  const others = rows.filter((r) => !r.model.includes(vehicleCode));
  if (ours.length === 0 || others.length === 0) {
    return { value: 50, rationale: "Matched customer-study categories but no same-region comparison model; defaulting to neutral." };
  }
  const ourMean = avg(ours.map((r) => r.mean));
  const bestOther = Math.max(...others.map((r) => r.mean));
  const gap = bestOther - ourMean; // positive = we're behind
  const value = clamp(Math.round(50 + gap * 15), 0, 100);
  return {
    value,
    rationale: `Customer study (${region}): we score ${ourMean.toFixed(2)}/10 vs. best sibling model ${bestOther.toFixed(2)}/10 on related categories.`,
  };
}

export function salesRelevance(vehicleCode: string, market: string, sales: SalesVolume[]): { value: number; rationale: string } {
  const row = sales.find((s) => s.vehicleCode === vehicleCode && s.market === market);
  if (!row || row.volume2025 === 0) {
    return { value: 30, rationale: `No ${market} sales volume on record for ${vehicleCode}.` };
  }
  const growth = (row.volume2030 - row.volume2025) / row.volume2025;
  const value = clamp(Math.round(50 + growth * 150), 0, 100);
  return {
    value,
    rationale: `${market} volume: ${row.volume2025.toLocaleString()} (2025) → ${row.volume2030.toLocaleString()} (2030 est.), ${(growth * 100).toFixed(0)}% growth.`,
  };
}

export function strategicFit(component: ComponentKey): { value: number; rationale: string } {
  const elevated: ComponentKey[] = ["battery", "steering"];
  return elevated.includes(component)
    ? { value: 70, rationale: "Aligned with BMW Group's stated electrification/connected-driving strategy." }
    : { value: 50, rationale: "No explicit strategic-priority signal found for this component; defaulting to neutral." };
}

export function buildScoreFactors(args: {
  candidate: Candidate;
  maxFrequencyInVehicle: number;
  component: ComponentKey;
  vehicleCode: string;
  region: "CN" | "EU" | "US";
  market: string;
  sales: SalesVolume[];
  study: CustomerStudyScore[];
}): ScoreFactor[] {
  const { candidate, maxFrequencyInVehicle, component, vehicleCode, region, market, sales, study } = args;
  const freqRaw = clamp(Math.round((candidate.signal.frequency / maxFrequencyInVehicle) * 100), 0, 100);
  const impactRaw = clamp(Math.round(candidate.concentration * 100), 0, 100);
  const gap = competitiveGap(component, vehicleCode, region, study);
  const sr = salesRelevance(vehicleCode, market, sales);
  const sf = strategicFit(component);
  const ev = evidenceLevel(candidate.signal.frequency) === "strong" ? 90 : evidenceLevel(candidate.signal.frequency) === "moderate" ? 65 : 35;

  return [
    { key: "customer_impact", label: "Customer impact", weight: 0.25, rawValue: impactRaw, rationale: `${Math.round(candidate.concentration * 100)}% of this theme's feedback shares the same sentiment (${candidate.kind}).` },
    { key: "frequency", label: "Signal frequency", weight: 0.15, rawValue: freqRaw, rationale: `${candidate.signal.frequency} verbatims, ${freqRaw}% of this vehicle's single largest theme.` },
    { key: "sales_relevance", label: "Sales relevance", weight: 0.15, rawValue: sr.value, rationale: sr.rationale },
    { key: "competitive_gap", label: "Competitive gap", weight: 0.15, rawValue: gap.value, rationale: gap.rationale },
    { key: "strategic_fit", label: "Strategic fit", weight: 0.1, rawValue: sf.value, rationale: sf.rationale },
    { key: "effort_inverse", label: "Feasibility (inverse effort)", weight: 0.1, rawValue: 50, rationale: "Not yet estimated — placeholder pending Engineering stakeholder review." },
    { key: "evidence_strength", label: "Evidence strength", weight: 0.1, rawValue: ev, rationale: `${candidate.signal.frequency} first-party verbatims → ${evidenceLevel(candidate.signal.frequency)} evidence.` },
  ];
}

function avg(nums: number[]): number {
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}
function clamp(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, n));
}

// Thin typed fetch wrappers around the API routes. Frontend roles (C & D)
// should only ever talk to the backend through this file, never fetch()
// directly in a component — if the API contract changes, this is the one
// file that needs an update.

import type {
  Vehicle,
  VehicleComponent,
  Workflow,
  Requirement,
  Signal,
  SourceRecord,
  Stakeholder,
  StakeholderReview,
  AuditLogEntry,
  AISummary,
  ReviewDecision,
  FeedbackRecord,
  CustomerStudyScore,
} from "./types";

export interface FeedbackPage {
  total: number;
  page: number;
  pageSize: number;
  rows: FeedbackRecord[];
  noData?: boolean;
}

export interface Facets {
  vehicleCodes: { value: string; count: number }[];
  components: { value: string; count: number }[];
  feedbackTypes: { value: string; count: number }[];
  countries: { value: string; count: number }[];
}

async function j<T>(res: Response): Promise<T> {
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error ?? `Request failed: ${res.status}`);
  }
  return res.json();
}

export const api = {
  listVehicles: () => fetch("/api/vehicles").then((r) => j<Vehicle[]>(r)),

  getVehicle: (id: string) => fetch(`/api/vehicles/${id}`).then((r) => j<Vehicle>(r)),

  listComponents: (vehicleId: string) =>
    fetch(`/api/components?vehicleId=${encodeURIComponent(vehicleId)}`).then((r) => j<VehicleComponent[]>(r)),

  getComponent: (id: string) => fetch(`/api/components/${id}`).then((r) => j<VehicleComponent>(r)),

  getWorkflowByComponent: (componentId: string) =>
    fetch(`/api/workflows/by-component/${componentId}`).then((r) => (r.status === 404 ? null : j<Workflow>(r))),

  getWorkflow: (id: string) => fetch(`/api/workflows/${id}`).then((r) => j<Workflow>(r)),

  createWorkflow: (componentId: string, market: string) =>
    fetch("/api/workflows", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ componentId, market }),
    }).then((r) => j<Workflow>(r)),

  listRequirements: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/requirements`).then((r) => j<Requirement[]>(r)),

  getRequirement: (id: string) => fetch(`/api/requirements/${id}`).then((r) => j<Requirement>(r)),

  updateRequirementStatus: (id: string, status: Requirement["status"], rationale?: string) =>
    fetch(`/api/requirements/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status, rationale }),
    }).then((r) => j<Requirement>(r)),

  updateWeights: (id: string, weights: Record<string, number>) =>
    fetch(`/api/requirements/${id}/weights`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ weights }),
    }).then((r) => j<Requirement>(r)),

  challengeRequirement: (id: string, argument: string) =>
    fetch(`/api/requirements/${id}/challenge`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ argument }),
    }).then((r) => j<{ changed: boolean; explanation: string }>(r)),

  getSignals: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/signals`).then((r) => j<{ signals: Signal[]; sources: SourceRecord[] }>(r)),

  getAuditLog: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/audit-log`).then((r) => j<AuditLogEntry[]>(r)),

  getAISummaries: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/ai-summaries`).then((r) => j<AISummary[]>(r)),

  listStakeholders: () => fetch("/api/stakeholders").then((r) => j<Stakeholder[]>(r)),

  listReviews: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/reviews`).then((r) => j<StakeholderReview[]>(r)),

  submitReview: (reviewId: string, decision: ReviewDecision, expertOpinion: string) =>
    fetch(`/api/reviews/${reviewId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ decision, expertOpinion }),
    }).then((r) => j<StakeholderReview>(r)),

  getFeedback: (params: Record<string, string | number | undefined>) => {
    const sp = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== "") sp.set(k, String(v));
    return fetch(`/api/feedback?${sp.toString()}`).then((r) => j<FeedbackPage>(r));
  },

  getFeedbackFacets: () => fetch("/api/feedback/facets").then((r) => j<Facets>(r)),

  getCustomerStudy: (workflowId: string) =>
    fetch(`/api/workflows/${workflowId}/customer-study`).then((r) => j<CustomerStudyScore[]>(r)),
};
// Loads the real-data JSON fixtures produced by `npm run ingest`
// (src/data/*.json, gitignored — confidential BMW hackathon data, each
// teammate needs their own copy of data-raw/ and must run the ingest
// script locally). Falls back to empty arrays if a teammate hasn't run it
// yet, so the app never crashes — it just has less to show.

import { existsSync, readFileSync } from "fs";
import { join } from "path";
import type { FeedbackRecord, SalesVolume, CustomerStudyScore } from "./types";

export interface RawSignal {
  vehicleCode: string;
  component: string;
  theme: string;
  frequency: number;
  likes: number;
  wants: number;
  difficultToUse: number;
  defect: number;
  none: number;
  sampleVerbatims: string[];
  feedbackIds: string[];
  countries: Record<string, number>;
}

export interface EquipmentChunk {
  vehicleCode: string;
  section: string;
  text: string;
}

function load<T>(filename: string, fallback: T): T {
  const path = join(process.cwd(), "src", "data", filename);
  if (!existsSync(path)) return fallback;
  try {
    return JSON.parse(readFileSync(path, "utf-8")) as T;
  } catch {
    return fallback;
  }
}

export function hasRealData(): boolean {
  return existsSync(join(process.cwd(), "src", "data", "signals.json"));
}

export function loadFeedback(): FeedbackRecord[] {
  return load("feedback.json", []);
}

export function loadSignals(): RawSignal[] {
  return load("signals.json", []);
}

export function loadSales(): SalesVolume[] {
  return load("sales.json", []);
}

export function loadCustomerStudy(): CustomerStudyScore[] {
  return load("customer-study.json", []);
}

export function loadEquipmentChunks(): EquipmentChunk[] {
  return load("equipment-chunks.json", []);
}

"use client";

