59	export function summarizeStakeholderReviews(input: StakeholderOverviewInput): string {
60	  const { reviews } = input;
61	  const submitted = reviews.filter((r) => r.decision !== "pending");
62	  const approvals = submitted.filter((r) => r.decision === "approve").length;
63	  const rejections = submitted.filter((r) => r.decision === "reject").length;
64	  const pending = reviews.length - submitted.length;
65	  if (submitted.length === 0) return "No stakeholder reviews submitted yet.";
66	  return `${approvals} approve, ${rejections} reject, ${pending} pending. ${
67	    rejections > 0
68	      ? `Rejection rationale: "${submitted.find((r) => r.decision === "reject")?.expertOpinion}"`
69	      : "No objections raised."
70	  }`;
