184	export function recomputeScore(req: Requirement): number {
185	  const totalWeight = req.scoreFactors.reduce((s, f) => s + f.weight, 0) || 1;
186	  const weighted = req.scoreFactors.reduce((s, f) => s + (f.rawValue * f.weight), 0);
187	  return Math.round((weighted / totalWeight) * 10) / 10;
188	}
