1	"use client";
2	
3	import { useState } from "react";
4	import clsx from "clsx";
5	import type { Requirement } from "@/lib/types";
6	import { EvidenceBadge } from "./EvidenceBadge";
7	import { api } from "@/lib/api-client";
8	
9	const STATUS_STYLE: Record<Requirement["status"], string> = {
10	  proposed: "bg-neutral-800 text-neutral-300 border-neutral-700",
11	  approved: "bg-emerald-950 text-emerald-300 border-emerald-800",
12	  rejected: "bg-red-950 text-red-300 border-red-800",
13	  postponed: "bg-amber-950 text-amber-300 border-amber-800",
14	  challenged: "bg-violet-950 text-violet-300 border-violet-800",
15	};
16	
17	export function RequirementCard({
18	  requirement,
19	  onChanged,
20	}: {
21	  requirement: Requirement;
22	  onChanged: (updated: Requirement) => void;
23	}) {
24	  const [expanded, setExpanded] = useState(false);
25	  const [weights, setWeights] = useState(
26	    Object.fromEntries(requirement.scoreFactors.map((f) => [f.key, f.weight])),
27	  );
28	  const [rationaleDraft, setRationaleDraft] = useState("");
29	  const [pending, setPending] = useState<string | null>(null);
30	  const [challengeArg, setChallengeArg] = useState("");
31	  const [challengeResult, setChallengeResult] = useState<{ changed: boolean; explanation: string } | null>(null);
32	
33	  const liveScore = computeLiveScore(requirement, weights);
34	  const weightsDirty = requirement.scoreFactors.some((f) => Math.abs(weights[f.key] - f.weight) > 0.001);
35	
36	  async function act(status: Requirement["status"]) {
37	    const needsRationale = status === "rejected" || status === "postponed";
38	    if (needsRationale && !rationaleDraft.trim()) {
39	      alert("A rationale is required for this decision.");
40	      return;
41	    }
42	    setPending(status);
43	    try {
44	      const updated = await api.updateRequirementStatus(requirement.id, status, rationaleDraft || undefined);
45	      onChanged(updated);
46	      setRationaleDraft("");
47	    } finally {
48	      setPending(null);
49	    }
50	  }
51	
52	  async function saveWeights() {
53	    setPending("weights");
54	    try {
55	      const updated = await api.updateWeights(requirement.id, weights);
56	      onChanged(updated);
57	    } finally {
58	      setPending(null);
59	    }
60	  }
61	
62	  async function sendChallenge() {
63	    if (!challengeArg.trim()) return;
64	    setPending("challenge");
65	    try {
66	      const result = await api.challengeRequirement(requirement.id, challengeArg);
67	      setChallengeResult(result);
68	      const updated = await api.getRequirement(requirement.id);
69	      onChanged(updated);
70	    } finally {
71	      setPending(null);
72	    }
73	  }
74	
75	  return (
76	    <div className="border border-neutral-800 bg-neutral-900/60">
77	      <div className="flex items-start justify-between gap-3 border-b border-neutral-800 p-3">
78	        <div className="min-w-0">
79	          <div className="flex flex-wrap items-center gap-2">
80	            <span className={clsx("border px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide", STATUS_STYLE[requirement.status])}>
81	              {requirement.status}
82	            </span>
83	            <EvidenceBadge level={requirement.evidenceLevel} />
84	            <span className="text-[11px] text-neutral-500">{requirement.category.replace(/_/g, " ")}</span>
85	          </div>
86	          <h3 className="mt-1.5 text-sm font-semibold text-neutral-100">{requirement.title}</h3>
87	          <p className="mt-1 text-xs leading-relaxed text-neutral-400">{requirement.description}</p>
88	        </div>
89	        <div className="flex shrink-0 flex-col items-end">
90	          <div className="font-mono text-xl font-bold tabular-nums text-neutral-100">{liveScore.toFixed(1)}</div>
91	          <div className="text-[10px] uppercase tracking-wide text-neutral-600">score{weightsDirty ? " · unsaved" : ""}</div>
92	        </div>
93	      </div>
94	
95	      {(requirement.assumptions.length > 0 || requirement.uncertainties.length > 0) && (
96	        <div className="divide-y divide-neutral-800 border-b border-neutral-800">
97	          {requirement.assumptions.map((a, i) => (
98	            <div key={i} className="flex gap-2 border-l-2 border-sky-600 bg-sky-950/30 px-3 py-1.5 text-[11px] text-sky-200">
99	              <span className="shrink-0 font-semibold text-sky-400">ASSUMPTION</span>
100	              <span>{a}</span>
101	            </div>
102	          ))}
103	          {requirement.uncertainties.map((u, i) => (
104	            <div key={i} className="flex gap-2 border-l-2 border-amber-600 bg-amber-950/20 px-3 py-1.5 text-[11px] text-amber-200">
105	              <span className="shrink-0 font-semibold text-amber-400">UNCERTAINTY</span>
106	              <span>{u}</span>
107	            </div>
108	          ))}
109	        </div>
110	      )}
111	
112	      <button
113	        onClick={() => setExpanded((v) => !v)}
114	        className="w-full border-b border-neutral-800 px-3 py-1.5 text-left text-[11px] font-medium text-neutral-500 hover:bg-neutral-800/50 hover:text-neutral-300"
115	      >
116	        {expanded ? "▾" : "▸"} Score breakdown ({requirement.scoreFactors.length} factors, adjustable weights)
117	      </button>
118	
119	      {expanded && (
120	        <div className="space-y-2.5 border-b border-neutral-800 bg-black/20 p-3">
121	          {requirement.scoreFactors.map((f) => (
122	            <div key={f.key}>
123	              <div className="flex items-center justify-between text-[11px] text-neutral-300">
124	                <span>
125	                  {f.label} <span className="font-mono text-neutral-500">raw={f.rawValue}</span>
126	                </span>
127	                <span className="font-mono tabular-nums text-neutral-400">w={Math.round(weights[f.key] * 100)}%</span>
128	              </div>
129	              <input
130	                type="range"
131	                min={0}
132	                max={1}
133	                step={0.05}
134	                value={weights[f.key]}
135	                onChange={(e) => setWeights((w) => ({ ...w, [f.key]: Number(e.target.value) }))}
136	                className="h-1 w-full accent-bmw-blue"
137	              />
138	              <p className="text-[10px] text-neutral-600">{f.rationale}</p>
139	            </div>
140	          ))}
141	          <button
142	            onClick={saveWeights}
143	            disabled={pending === "weights"}
144	            className="bg-bmw-blue px-3 py-1.5 text-xs font-semibold text-white hover:bg-sky-500 disabled:opacity-50"
145	          >
146	            {pending === "weights" ? "Saving…" : "Save weights & recompute"}
147	          </button>
148	        </div>
149	      )}
150	
151	      <div className="flex flex-wrap items-center gap-2 border-b border-neutral-800 p-3">
152	        <button
153	          onClick={() => act("approved")}
154	          disabled={!!pending}
155	          className="bg-emerald-700 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-600 disabled:opacity-50"
156	        >
157	          Approve
158	        </button>
159	        <button
160	          onClick={() => act("rejected")}
161	          disabled={!!pending}
162	          className="bg-red-800 px-3 py-1.5 text-xs font-semibold text-white hover:bg-red-700 disabled:opacity-50"
163	        >
164	          Reject
165	        </button>
166	        <button
167	          onClick={() => act("postponed")}
168	          disabled={!!pending}
169	          className="bg-amber-800 px-3 py-1.5 text-xs font-semibold text-white hover:bg-amber-700 disabled:opacity-50"
170	        >
171	          Postpone
172	        </button>
173	        <input
174	          value={rationaleDraft}
175	          onChange={(e) => setRationaleDraft(e.target.value)}
176	          placeholder="Rationale (required for reject/postpone)"
177	          className="min-w-[220px] flex-1 border border-neutral-700 bg-black/30 px-2 py-1.5 text-xs text-neutral-200 placeholder:text-neutral-600"
178	        />
179	      </div>
180	
181	      <div className="p-3">
182	        <div className="flex items-center gap-2">
183	          <input
184	            value={challengeArg}
185	            onChange={(e) => setChallengeArg(e.target.value)}
186	            placeholder="Challenge this score/rationale with your own argument…"
187	            className="flex-1 border border-neutral-700 bg-black/30 px-2 py-1.5 text-xs text-neutral-200 placeholder:text-neutral-600"
188	          />
189	          <button
190	            onClick={sendChallenge}
191	            disabled={pending === "challenge"}
192	            className="border border-violet-700 bg-violet-950 px-3 py-1.5 text-xs font-semibold text-violet-200 hover:bg-violet-900 disabled:opacity-50"
193	          >
194	            {pending === "challenge" ? "Re-assessing…" : "Challenge"}
195	          </button>
196	        </div>
197	        {challengeResult && (
198	          <p className={clsx("mt-2 border-l-2 pl-2 text-xs", challengeResult.changed ? "border-emerald-600 text-emerald-300" : "border-neutral-600 text-neutral-400")}>
199	            {challengeResult.changed ? "Result changed: " : "Result unchanged: "}
200	            {challengeResult.explanation}
201	          </p>
202	        )}
203	      </div>
204	    </div>
205	  );
206	}
207	
208	function computeLiveScore(requirement: Requirement, weights: Record<string, number>) {
209	  const totalWeight = requirement.scoreFactors.reduce((s, f) => s + (weights[f.key] ?? f.weight), 0) || 1;
210	  const weighted = requirement.scoreFactors.reduce(
211	    (s, f) => s + f.rawValue * (weights[f.key] ?? f.weight),
212	    0,
213	  );
214	  return weighted / totalWeight;
215	}
