// A fallback (template) result never overwrites an existing summary of the
// same type — e.g. the seeded flagship narrative stays put if the API is
// down mid-demo. It is only stored when there is nothing better to show.
function save(workflowId: string, type: AISummary["type"], result: AIText, basedOnLogIds: string[]): AISummary | null {
  const existing = listAISummaries(workflowId).find((s) => s.type === type);
  if (!result.live && existing) return null;
  return addAISummary({ workflowId, type, content: result.text, basedOnLogIds }, result.model);
}

